import{_ as n,C as l,o as s,c as t,E as o,a2 as i}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"Weekly 001 — 从 Agent 框架走向可治理数字员工","description":"","frontmatter":{"title":"Weekly 001 — 从 Agent 框架走向可治理数字员工","date":"2026-07-31","column":"digital-employee","category":"weekly","summary":"首期综合互操作协议、开源 Runtime 工程、企业数字劳动力产品与 CodeFlowMu 定位。","outline":"deep","cover":"/assets/covers/weekly-001-cover-v2.jpg"},"headers":[],"relativePath":"zh/research/weekly/weekly-001.md","filePath":"zh/research/weekly/weekly-001.md","lastUpdated":1787407830000}'),r={name:"zh/research/weekly/weekly-001.md"};function p(c,e,d,h,u,m){const a=l("ArticleCover");return s(),t("div",null,[o(a,{image:"/assets/covers/weekly-001-cover-v2.jpg",kicker:"研究周报 · 001",title:"从 Agent 框架走向可治理数字员工",summary:"首期综合互操作协议、开源 Runtime 工程、企业数字劳动力产品与 CodeFlowMu 定位。",version:"W001",status:"发布于 2026-07-31",languageHref:"/en/research/weekly/weekly-001",languageLabel:"English"}),e[0]||(e[0]=i(`<h2 id="核心综合" tabindex="-1">核心综合 <a class="header-anchor" href="#核心综合" aria-label="Permalink to &quot;核心综合&quot;">​</a></h2><p>首期周报建立了 Research Center 的研究基线：</p><ol><li>互操作正在成为基础设施，而治理仍是缺失上层；</li><li>开源系统正从聊天 Agent 转向 Runtime、编排和操作者控制；</li><li>企业厂商正在封装数字劳动力产品，而不是抽象 Agent 能力；</li><li>CodeFlowMu 不应成为另一个通用多 Agent 框架；</li><li>稳定方向是面向中小企业的数字员工开发与运行平台。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数字员工</span></span>
<span class="line"><span>= 岗位</span></span>
<span class="line"><span>+ 职责</span></span>
<span class="line"><span>+ Skill</span></span>
<span class="line"><span>+ Workflow</span></span>
<span class="line"><span>+ Runtime</span></span>
<span class="line"><span>+ 治理</span></span>
<span class="line"><span>+ 评估</span></span></code></pre></div><h2 id="学术信号" tabindex="-1">学术信号 <a class="header-anchor" href="#学术信号" aria-label="Permalink to &quot;学术信号&quot;">​</a></h2><p>围绕 MCP、A2A、ACP 等协议的研究表明，工具访问和互操作并不会自动提供成员关系、责任、异议、人类升级、审计和回放。TMPA 因此应位于互操作协议之上或旁侧，成为工作数据与治理架构，而不是竞争另一个通用通信协议。</p><h2 id="开源工程信号" tabindex="-1">开源工程信号 <a class="header-anchor" href="#开源工程信号" aria-label="Permalink to &quot;开源工程信号&quot;">​</a></h2><p>OpenHands、AutoGen 等系统正增加可恢复执行、嵌套团队、Skill、Plugin、MCP 集成、连接健康和操作者控制。这些正在成为 Runtime 基础能力，但仍未定义持久组织岗位、责任所有者、完成证据和发布权威。</p><h2 id="企业信号" tabindex="-1">企业信号 <a class="header-anchor" href="#企业信号" aria-label="Permalink to &quot;企业信号&quot;">​</a></h2><ul><li><strong>ServiceNow</strong> 把岗位化 AI Specialist 放入确定性工作流、升级和集中治理；</li><li><strong>Workday</strong> 把 Agent 当作具有所有权、成本、合规和生命周期的劳动力资源；</li><li><strong>Salesforce</strong> 按业务职能封装结果，而不是销售抽象多 Agent 能力。</li></ul><p>市场信号很明确：组织购买的是完成的工作，而不是框架术语。</p><h2 id="对-tmpa-的影响" tabindex="-1">对 TMPA 的影响 <a class="header-anchor" href="#对-tmpa-的影响" aria-label="Permalink to &quot;对 TMPA 的影响&quot;">​</a></h2><p>TMPA 应保持协议无关，把治理定义为可执行生命周期控制，坚持 SME-first 定位，并评估证据、升级、恢复、人类介入和成本，而不是只看任务成功。</p><h2 id="对-codeflowmu-的影响" tabindex="-1">对 CodeFlowMu 的影响 <a class="header-anchor" href="#对-codeflowmu-的影响" aria-label="Permalink to &quot;对 CodeFlowMu 的影响&quot;">​</a></h2><p>建议正式定位为：</p><blockquote><p><strong>CodeFlowMu 是面向中小企业的数字员工开发与运行平台。</strong></p></blockquote><p>初期重点是岗位定义、数字员工名册、Workflow 与 Operation Node 契约、Runtime 可观测与恢复、TMPA/FCoP 证据生命周期，以及成本与评估记录。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>CodeFlowMu 的价值不在 Agent 数量，而在于把概率型执行转化为可问责、可恢复、可度量成本和价值的组织工作。</p>`,19))])}const w=n(r,[["render",p]]);export{k as __pageData,w as default};
